import { MakeLogicType, afterMount, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { mcpGatewayServiceAccountsList } from 'products/mcp_store/frontend/generated/api'
import type { MCPServiceAccountApi } from 'products/mcp_store/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskServiceAccountPickerLogicValues {
    currentProjectId: number | null // projectLogic
    selectableServiceAccounts: MCPServiceAccountApi[]
    serviceAccounts: MCPServiceAccountApi[]
    serviceAccountsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskServiceAccountPickerLogicActions {
    loadServiceAccounts: () => any
    loadServiceAccountsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadServiceAccountsSuccess: (
        serviceAccounts: MCPServiceAccountApi[],
        payload?: any
    ) => {
        serviceAccounts: MCPServiceAccountApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskServiceAccountPickerLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        selectableServiceAccounts: (serviceAccounts: MCPServiceAccountApi[]) => MCPServiceAccountApi[]
    }
}

export type taskServiceAccountPickerLogicType = MakeLogicType<
    taskServiceAccountPickerLogicValues,
    taskServiceAccountPickerLogicActions,
    Record<string, any>,
    taskServiceAccountPickerLogicMeta
>

export const taskServiceAccountPickerLogic = kea<taskServiceAccountPickerLogicType>([
    path(['products', 'tasks', 'frontend', 'components', 'TaskServiceAccountPicker', 'taskServiceAccountPickerLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        serviceAccounts: [
            [] as MCPServiceAccountApi[],
            {
                loadServiceAccounts: async (): Promise<MCPServiceAccountApi[]> => {
                    const response = await mcpGatewayServiceAccountsList(String(values.currentProjectId), {
                        limit: 500,
                    })
                    return response.results
                },
            },
        ],
    })),
    selectors({
        // Built-in agents (support, scout) are excluded: their grants are scoped to
        // their own product surface, not to arbitrary workflow-authored prompts.
        selectableServiceAccounts: [
            (s) => [s.serviceAccounts],
            (serviceAccounts: MCPServiceAccountApi[]): MCPServiceAccountApi[] =>
                serviceAccounts.filter((account) => account.kind === 'custom'),
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadServiceAccounts()
    }),
])
